text(await tools.exec_command({cmd:"cat /Users/ab/.agents/skills/find-docs/SKILL.md","max_output_tokens":7000}));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat AGENTS.md && rg --files -g AGENTS.md packages .github && git ls-files '*Container*' '*composer*' '.github/*' 'build/*'","max_output_tokens":10000}),
  tools.exec_command({cmd:"rg -n 'Testcontainers|Container\\\\|Container;|new .*Container|docker|mysql:[0-9]|postgres:[0-9]' packages .github build README.md -g '*.php' -g '*.json' -g '*.yml' -g '*.yaml' -g '*.md' -g '!vendor/**' -g '!**/.phpstan.cache/**'","max_output_tokens":12000}),
  tools.exec_command({cmd:"cat packages/sql-faker/composer.json packages/ztd-query-pdo-adapter/composer.json packages/sql-fixture/composer.json packages/phpstan-custom-rules/composer.json && cat README.md","max_output_tokens":10000}),
  tools.exec_command({cmd:"npx --yes ctx7@latest library composer 'Composer path repository local monorepo package require-dev and dependency repositories root only'","yield_time_ms":1000,"max_output_tokens":3000})
]);
for(let i=0;i<results.length;i++) text({i,...results[i]});

