            } catch (\PDOException $e) {
                $this->logger()->debug(sprintf('Unable to connect to PDO: %s', $e->getMessage()), [
                    'exception' => $e,
                ]);
                $ex = $e;
            }
            usleep($this->retryInterval);
        }

        ini_set('default_socket_timeout', $defaultSocketTimeout);
    }
}
