        raise SystemExit(1)
    if checks and not any(x['state'] in ['IN_PROGRESS','QUEUED','PENDING','WAITING','REQUESTED'] for x in checks):
        print('All checks completed successfully.',flush=True)
        break
    time.sleep(30)
